\textbf{4.1.} Let $(\Omega, \mathcal{F})$ be a measurable space and $f$ be a function from $\Omega$ to $\mathbb{R}$. Show that if one of the following conditions hold:
\begin{itemize}
    \item $f^{-1}((\infty, a)) \in \mathcal{F}$ for all $a \in \mathbb{R}$
    \item $f^{-1}((\infty, a]) \in \mathcal{F}$ for all $a \in \mathbb{R}$
\end{itemize}
then $f$ is $(\mathcal{F}, \mathcal{B}(\mathbb{R}))$-measurable.

\textbf{4.8.}
\begin{enumerate}[label=(\alph*)]
    \item Find $\limsup_{n \to \infty} \sin(n\pi/3)$ and $\liminf_{n \to \infty} \sin(n\pi/3)$.
    \item For $k \ge 1$, define
    \[
    a_k = \begin{cases} \log(k) & \text{if } k \text{ is odd} \\ 1/k & \text{if } k \text{ is even.} \end{cases}
    \]
    Find the limsup and liminf of the sequence $(a_k)_{k=1}^{\infty}$.
\end{enumerate}
